import fs from "node:fs";
import path from "node:path";
import { spawnSync } from "node:child_process";

const REPORT_DIR = path.resolve(".github/seo-reports");

const webhook = process.env.DISCORD_WEBHOOK_URL;
const deployUrl = process.env.DEPLOY_URL || "";
const githubRunUrl = process.env.GITHUB_RUN_URL || "";

if (!webhook) {
  throw new Error(
    "DISCORD_SEO_ACCESSIBILITY_WEBHOOK secret is not configured."
  );
}

const summaryPath = path.join(
  REPORT_DIR,
  "audit-summary.json"
);

if (!fs.existsSync(summaryPath)) {
  throw new Error("audit-summary.json was not generated.");
}

const summary = JSON.parse(
  fs.readFileSync(summaryPath, "utf8")
);

const scoreEmoji = (score) => {
  if (score === null || score === undefined) {
    return "⚪";
  }

  if (score >= 90) return "🟢";
  if (score >= 75) return "🟡";
  if (score >= 50) return "🟠";

  return "🔴";
};

const differenceText = (value) => {
  if (value === null || value === undefined) {
    return "N/A";
  }

  if (value > 0) return `+${value}`;
  return String(value);
};

const severity = (value) => {
  if (value === 0) return "🟢";
  if (value <= 2) return "🟡";
  if (value <= 5) return "🟠";
  return "🔴";
};

const lighthouseEmbed = {
  title: "🔎 Lighthouse Audit",
  description:
    "SEO and accessibility results for the exact production build generated by this GitHub Actions run.",
  color: 0x5865f2,

  fields: [
    {
      name: "💻 Offline — GitHub Actions Build",
      value:
        `**SEO:** ${scoreEmoji(summary.lighthouse.offline.seo)} ` +
        `**${summary.lighthouse.offline.seo ?? "N/A"}/100**\n` +
        `**Accessibility:** ${scoreEmoji(summary.lighthouse.offline.accessibility)} ` +
        `**${summary.lighthouse.offline.accessibility ?? "N/A"}/100**\n` +
        `Failed audits: **${summary.lighthouse.offline.failedAudits?.length ?? 0}**`,
      inline: true,
    },

    {
      name: "🌐 Online — Temporary Netlify",
      value:
        `**SEO:** ${scoreEmoji(summary.lighthouse.online.seo)} ` +
        `**${summary.lighthouse.online.seo ?? "N/A"}/100**\n` +
        `**Accessibility:** ${scoreEmoji(summary.lighthouse.online.accessibility)} ` +
        `**${summary.lighthouse.online.accessibility ?? "N/A"}/100**\n` +
        `Failed audits: **${summary.lighthouse.online.failedAudits?.length ?? 0}**`,
      inline: true,
    },

    {
      name: "📊 Offline → Online Difference",
      value:
        `SEO: **${differenceText(summary.lighthouse.difference.seo)}**\n` +
        `Accessibility: **${differenceText(summary.lighthouse.difference.accessibility)}**`,
      inline: false,
    },

    {
      name: "📎 Reports",
      value:
        "[Offline Lighthouse](attachment://lighthouse-offline.json)\n" +
        "[Online Lighthouse](attachment://lighthouse-online.json)",
      inline: false,
    },
  ],

  footer: {
    text: `4rm0Byte • GitHub Actions Run #${summary.run.number}`,
  },

  timestamp: summary.generatedAt,
};

const pa11yEmbed = {
  title: "♿ Pa11y Accessibility Audit",
  description:
    "Accessibility findings from Pa11y against both the local production artifact and its temporary hosted deployment.",

  color: 0x57f287,

  fields: [
    {
      name: "💻 Offline — GitHub Actions Build",
      value:
        `${severity(summary.pa11y.offline.errors)} Errors: **${summary.pa11y.offline.errors}**\n` +
        `Warnings: **${summary.pa11y.offline.warnings}**\n` +
        `Notices: **${summary.pa11y.offline.notices}**\n` +
        `Total findings: **${summary.pa11y.offline.total}**`,
      inline: true,
    },

    {
      name: "🌐 Online — Temporary Netlify",
      value:
        `${severity(summary.pa11y.online.errors)} Errors: **${summary.pa11y.online.errors}**\n` +
        `Warnings: **${summary.pa11y.online.warnings}**\n` +
        `Notices: **${summary.pa11y.online.notices}**\n` +
        `Total findings: **${summary.pa11y.online.total}**`,
      inline: true,
    },

    {
      name: "📊 Offline → Online Difference",
      value:
        `Errors: **${differenceText(summary.pa11y.difference.errors)}**\n` +
        `Warnings: **${differenceText(summary.pa11y.difference.warnings)}**\n` +
        `Total: **${differenceText(summary.pa11y.difference.total)}**`,
      inline: false,
    },

    {
      name: "📎 Reports",
      value:
        "[Offline Pa11y](attachment://pa11y-offline.json)\n" +
        "[Online Pa11y](attachment://pa11y-online.json)",
      inline: false,
    },
  ],

  footer: {
    text: `4rm0Byte • Pa11y • Run #${summary.run.number}`,
  },

  timestamp: summary.generatedAt,
};

const axeEmbed = {
  title: "🛡️ axe-core Accessibility Audit",
  description:
    "Automated accessibility rule analysis comparing the local production artifact with the hosted deployment.",

  color: 0xed4245,

  fields: [
    {
      name: "💻 Offline — GitHub Actions Build",
      value:
        `${severity(summary.axe.offline.violations)} Violations: **${summary.axe.offline.violations}**\n` +
        `Incomplete: **${summary.axe.offline.incomplete}**\n` +
        `Passes: **${summary.axe.offline.passes}**`,
      inline: true,
    },

    {
      name: "🌐 Online — Temporary Netlify",
      value:
        `${severity(summary.axe.online.violations)} Violations: **${summary.axe.online.violations}**\n` +
        `Incomplete: **${summary.axe.online.incomplete}**\n` +
        `Passes: **${summary.axe.online.passes}**`,
      inline: true,
    },

    {
      name: "📊 Offline → Online Difference",
      value:
        `Violations: **${differenceText(summary.axe.difference.violations)}**\n` +
        `Incomplete: **${differenceText(summary.axe.difference.incomplete)}**\n` +
        `Passes: **${differenceText(summary.axe.difference.passes)}**`,
      inline: false,
    },

    {
      name: "📎 Reports",
      value:
        "[Offline axe](attachment://axe-offline.json)\n" +
        "[Online axe](attachment://axe-online.json)",
      inline: false,
    },
  ],

  footer: {
    text: `4rm0Byte • axe-core • Run #${summary.run.number}`,
  },

  timestamp: summary.generatedAt,
};

const overviewEmbed = {
  title: "🚀 4rm0Byte Website Quality Report",
  description:
    "The production build has been built, audited locally, and audited again after being deployed to a temporary Netlify URL.",

  color: 0x5865f2,

  fields: [
    {
      name: "🌐 Temporary Test Deployment",
      value: deployUrl
        ? `[Open temporary deployment](${deployUrl})`
        : "Unavailable",
      inline: false,
    },

    {
      name: "📦 Production Build",
      value:
        "The audits were run against the exact `public/` directory generated by `npm run build`.",
      inline: false,
    },

    {
      name: "🔎 Lighthouse",
      value:
        `SEO: **${summary.lighthouse.offline.seo ?? "N/A"} → ${summary.lighthouse.online.seo ?? "N/A"}**\n` +
        `Accessibility: **${summary.lighthouse.offline.accessibility ?? "N/A"} → ${summary.lighthouse.online.accessibility ?? "N/A"}**`,
      inline: true,
    },

    {
      name: "♿ Pa11y",
      value:
        `Errors: **${summary.pa11y.offline.errors} → ${summary.pa11y.online.errors}**\n` +
        `Warnings: **${summary.pa11y.offline.warnings} → ${summary.pa11y.online.warnings}**`,
      inline: true,
    },

    {
      name: "🛡️ axe-core",
      value:
        `Violations: **${summary.axe.offline.violations} → ${summary.axe.online.violations}**\n` +
        `Passes: **${summary.axe.offline.passes} → ${summary.axe.online.passes}**`,
      inline: true,
    },

    {
      name: "🔗 GitHub Actions",
      value: `[Open workflow run](${githubRunUrl})`,
      inline: false,
    },
  ],

  footer: {
    text: `4rm0Byte • SEO & Accessibility • Run #${summary.run.number}`,
  },

  timestamp: summary.generatedAt,
};

const payload = {
  username: "4rm0Byte CI",
  embeds: [
    overviewEmbed,
    lighthouseEmbed,
    pa11yEmbed,
    axeEmbed,
  ],
  allowed_mentions: {
    parse: [],
  },
};

const files = [
  "lighthouse-offline.json",
  "lighthouse-online.json",
  "pa11y-offline.json",
  "pa11y-online.json",
  "axe-offline.json",
  "axe-online.json",
  "audit-summary.json",
];

const args = [
  "-sS",
  "-X",
  "POST",
  webhook,
  "-F",
  `payload_json=${JSON.stringify(payload)}`,
];

for (const filename of files) {
  const fullPath = path.join(REPORT_DIR, filename);

  if (!fs.existsSync(fullPath)) {
    console.warn(`Skipping missing report: ${filename}`);
    continue;
  }

  args.push(
    "-F",
    `files[]=@${fullPath};filename=${filename};type=application/json`
  );
}

console.log("Sending audit results to Discord...");

const result = spawnSync("curl", args, {
  stdio: "inherit",
});

if (result.status !== 0) {
  throw new Error(
    `Discord webhook failed with exit code ${result.status}`
  );
}

console.log("Discord audit report sent successfully.");
